/**
 * PREPARE_AND_EXECUTE replies captured byte for byte from live brokers.
 *
 * The frames came from a raw socket client sending each `sql` to the
 * cubrid/cubrid:10.2, 11.0, 11.2 and 11.4 images with protocol version 7. They
 * are literal bytes, never produced by the decoder or the enums under test.
 * Every frame below is from 11.4; the four servers sent identical bytes for all
 * of them except `tableRows` (10.2 and 11.0 omit the `dba.` schema prefix from
 * the table name) and the frames holding a server path or OID, `blobElement`
 * and `objectElement`. The `zero*` frames were captured on all four and are
 * identical (`zeroDateElement` on 10.2 and 11.4 only, also identical). Provenance: docs/PROTOCOL_ORACLES.md.
 */
export interface CapturedFrame {
  sql: string;
  hex: string;
}

